const THEME_KEY="chinagraph-theme",DARK_THEME="dark",LIGHT_THEME="light",root=document.documentElement,themeToggle=document.querySelector(".theme-toggle");function getPreferredTheme(){const e=localStorage.getItem(THEME_KEY);return"dark"===e||"light"===e?e:window.matchMedia("(prefers-color-scheme: dark)").matches?"dark":"light"}function applyTheme(e){const t="dark"===e;root.dataset.theme=e,themeToggle&&(themeToggle.setAttribute("aria-pressed",String(t)),themeToggle.setAttribute("aria-label",t?"Switch to light theme":"Switch to dark theme"))}function toggleTheme(){const e="dark"===root.dataset.theme?"light":"dark";localStorage.setItem(THEME_KEY,e),applyTheme(e)}applyTheme(getPreferredTheme()),themeToggle?.addEventListener("click",toggleTheme);